const distinctTypes = (army: Card[]): Set<string> => new Set(army.map(typeOf));

const NO_SPHINX_SCORE = 0;
const FREE_TYPES = 3;
const SCORE_WITHIN_FREE_TYPES = 2;
const BASE_SCORE_BEYOND_FREE_TYPES = 1;
const POINTS_PER_EXTRA_TYPE = 2;

const scoreOneSphinx = (otherTypes: number): number => {
  if (otherTypes <= FREE_TYPES) return SCORE_WITHIN_FREE_TYPES;

  const extraTypes = otherTypes - FREE_TYPES;
  return BASE_SCORE_BEYOND_FREE_TYPES + POINTS_PER_EXTRA_TYPE * extraTypes;
};

export const scoreArmy = (army: Card[]): number => {
  const sphinxes = army.filter((card) => typeOf(card) === SPHINX);
  if (sphinxes.length === 0) return NO_SPHINX_SCORE;

  // A Sphinx counts the types it sees among the *other* cards. Sphinx is
  // one of those types only when another Sphinx card is present.
  const types = distinctTypes(army);
  const ONLY_SPHINX = 1;
  const otherTypes =
    sphinxes.length === ONLY_SPHINX ? types.size - ONLY_SPHINX : types.size;

  return sphinxes.length * scoreOneSphinx(otherTypes);
};

