const countTypesVisibleToASphinx = (
  army: Card[],
  sphinxCount: number,
): number => {
  const anotherSphinxSuppliesTheType = sphinxCount > 1;
  const ownType = anotherSphinxSuppliesTheType ? 0 : 1;
  return countDistinctTypes(army) - ownType;
};

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter((card) => typeOf(card) === SPHINX).length;
  if (sphinxCount === 0) return NO_SPHINX_SCORE;

  const visibleTypes = countTypesVisibleToASphinx(army, sphinxCount);
  return sphinxCount * scoreOneSphinx(visibleTypes);
};
